'use strict';
const app = document.getElementById('app');
const overlay = document.getElementById('overlay');
const state = {user:null, account:null, transactions:[], accounts:[], adminTransactions:[], csrf:null, reveal:false, filter:'ALL', search:'', routeVersion:0};
const esc = value => String(value ?? '').replace(/[&<>"']/g, char => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
const icon = name => `<i data-lucide="${name}" class="icon" aria-hidden="true"></i>`;
const money = value => new Intl.NumberFormat('en-PH',{style:'currency',currency:'PHP',minimumFractionDigits:2}).format(Number(value));
const date = (value,full=false) => new Intl.DateTimeFormat('en-PH',{month:full?'long':'short',day:'numeric',year:'numeric',...(full?{hour:'numeric',minute:'2-digit'}:{})}).format(new Date(value));
const masked = number => `•••• •••• ${String(number).slice(-4)}`;
const fullName = p => `${p.firstName} ${p.lastName}`;
const initials = p => esc((p.firstName[0]||'')+(p.lastName[0]||''));
const badge = status => `<span class="badge ${status==='FROZEN'?'frozen':''}">${status==='FROZEN'?'Frozen':status==='COMPLETED'?'Completed':'Active'}</span>`;
const label = type => ({DEPOSIT:'Deposit',WITHDRAWAL:'Withdrawal',TRANSFER_OUT:'Transfer out',TRANSFER_IN:'Transfer in',TRANSFER:'Transfer'})[type]||type;
const renderIcons = () => { if(window.lucide) lucide.createIcons(); };
async function csrf() {
 try { const response=await fetch('/api/csrf',{cache:'no-store'});if(!response.ok)throw new Error();state.csrf=await response.json();return state.csrf; }
 catch {state.csrf=null;throw {message:'We could not refresh your secure session. Please try again.'};}
}
function endSession() {
 state.user=null;state.account=null;state.transactions=[];state.accounts=[];state.adminTransactions=[];state.csrf=null;state.reveal=false;
 state.loginMessage='Your session has ended. Please log in again.';location.hash='login';
}
async function api(path, options={}) {
  const headers = {...(options.body?{'Content-Type':'application/json'}:{}),...options.headers};
  if(options.method && options.method!=='GET') { const token=await csrf(); headers[token.headerName]=token.token; }
  let response;
  try { response=await fetch('/api'+path,{...options,headers}); } catch { throw {message:'We could not reach VelisBank. Check your connection and try again. Your request reference is kept for a safe retry.'}; }
  const data=response.status===204?null:await response.json().catch(()=>({message:'Something went wrong. Please try again.'}));
  if(!response.ok) { if(response.status===401 && !['/login','/me'].includes(path)) { endSession(); } throw {...data,status:response.status}; }
  return data;
}
function toast(message) { const el=document.getElementById('toast');el.textContent=message;el.classList.add('visible');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove('visible'),4500); }
function errors(form,error) {
  form.querySelectorAll('.field-error').forEach(el=>el.textContent='');form.querySelectorAll('.invalid').forEach(el=>el.classList.remove('invalid'));
  form.querySelectorAll('[aria-invalid]').forEach(el=>el.removeAttribute('aria-invalid'));
  const box=form.querySelector('.form-error');if(box) box.textContent=error.message||'Please try again.';
  for(const [name,message] of Object.entries(error.errors||{})) { const input=form.elements.namedItem(name);if(input) {input.closest('.field')?.classList.add('invalid');input.setAttribute('aria-invalid','true');const target=input.closest('.field')?.querySelector('.field-error');if(target) target.textContent=message;} }
  form.querySelector('[aria-invalid="true"]')?.focus();
}
function formValues(form) { return Object.fromEntries(new FormData(form)); }
function field(name,title,type='text',value='',opts={}) {
  const id=`field-${name}`;
  let input=type==='textarea'?`<textarea id="${id}" name="${name}" maxlength="${opts.max||240}" ${opts.optional?'':'required'} aria-describedby="error-${name}">${esc(value)}</textarea>`:`<input id="${id}" name="${name}" type="${type}" value="${esc(value)}" ${opts.optional?'':'required'} ${opts.max?`maxlength="${opts.max}"`:''} ${opts.min?`minlength="${opts.min}"`:''} ${opts.autocomplete?`autocomplete="${opts.autocomplete}"`:''} ${opts.placeholder?`placeholder="${esc(opts.placeholder)}"`:''} ${opts.pattern?`pattern="${opts.pattern}"`:''} aria-describedby="error-${name}">`;
  if(type==='password') input=`<div class="input-wrap">${input}<button type="button" data-password="${id}" aria-label="Show password">${icon('eye')}</button></div>`;
  return `<div class="field"><label for="${id}">${title}</label>${input}${opts.hint?`<span class="field-hint">${opts.hint}</span>`:''}<span class="field-error" id="error-${name}"></span></div>`;
}
function info(rows) { return `<dl class="info-list">${rows.map(([key,value])=>`<div class="info-row"><dt>${key}</dt><dd>${value}</dd></div>`).join('')}</dl>`; }
function brand() { return `<a class="brand" href="#${state.user?'dashboard':'home'}"><img class="brandmark" src="/vendor/velis-logo.svg" alt="" width="39" height="39">VelisBank</a>`; }
function empty(title='No transactions yet',description='Your banking activity will appear here after your first transaction.') { return `<div class="empty">${icon('receipt-text')}<h3>${title}</h3><p>${description}</p></div>`; }
function sampleBalanceCard(a,sample=false) { return `<div class="balance-card"><div class="balance-top">${!sample&&state.user?.role==='CUSTOMER'?`<a class="balance-title card-destination" href="#account" aria-label="View savings account">${icon('wallet-cards')} Savings Account ${icon('arrow-up-right')}</a>`:`<span class="card-bank-brand"><img src="/favicon.svg" alt="" width="32" height="32"><span>VelisBank<small>Savings account</small></span></span>`}${badge(a.status)}</div><div class="balance-label">Available balance</div><div class="balance-value">${money(a.balance)}</div><div class="balance-bottom"><div class="balance-number"><small>Account number</small><span id="balance-number">${esc(state.reveal&&!sample?a.number:masked(a.number))}</span></div>${sample?`<span class="balance-brand">VelisBank</span>`:`<button class="text-btn" data-action="reveal">${icon(state.reveal?'eye-off':'eye')}<span>${state.reveal?'Hide':'Show'} number</span></button>`}</div></div>`; }
function balanceCard(a,sample=false) {
 if(sample)return sampleBalanceCard(a,true);
 const number=`<span class="account-number-control"><span data-account-number>${masked(a.number)}</span><button type="button" class="number-toggle" data-action="toggle-account-number" aria-label="Show account number" aria-pressed="false">${icon('eye')}</button></span>`;
 return `<div class="flip-shell"><div class="flip-inner"><section class="balance-card flip-front"><div class="balance-top"><span class="card-bank-brand"><img src="/favicon.svg" alt="" width="32" height="32"><span>VelisBank<small>Savings account</small></span></span>${badge(a.status)}</div><div class="balance-label">Available balance</div><div class="balance-value">${money(a.balance)}</div><div class="balance-bottom"><div class="balance-number"><small>Account number</small>${number}</div></div></section><section class="balance-card flip-back" aria-hidden="true" inert><div class="flip-heading"><h2>Account information</h2></div>${info([['Account holder',esc(fullName(a.customer))],['Account type','Savings'],['Account number',number],['Account status',badge(a.status)]])}</section></div><button type="button" class="text-btn flip-toggle" data-action="flip-account" aria-expanded="false">${icon('rotate-3d')}<span>Show details</span></button></div>`;
}
function accountInfo(a) { return `<section class="card"><div class="card-head"><h2>${state.user?.role==='CUSTOMER'?'<a class="card-destination" href="#account">Account information</a>':'Account information'}</h2>${icon('landmark')}</div>${info([['Account holder',esc(fullName(a.customer))],['Account type','Savings'],['Account number',esc(a.number)],['Account status',badge(a.status)]])}<div class="info-foot">${icon('shield-check')} Your account, all in one place.</div></section>`; }
function frozen(a) { return a.status==='FROZEN'?`<div class="warning" role="status">${icon('circle-alert')}<div><strong>Account temporarily frozen</strong><p>Deposits, withdrawals, and transfers are unavailable. You can still view your account, history, and profile.</p></div></div>`:''; }
function transactionRows(rows) { return rows.length?`<div class="transaction-list">${rows.map(t=>`<button class="transaction-row" data-transaction="${t.id}"><span class="tx-icon ${t.amount<0?'out':''}">${icon(t.type==='DEPOSIT'?'landmark':t.type==='WITHDRAWAL'?'banknote':'arrow-left-right')}</span><span class="tx-main"><span class="tx-name">${esc(t.type.startsWith('TRANSFER')?`${t.amount<0?'Transfer to':'Transfer from'} ${t.counterpartyName}`:label(t.type))}</span><span class="tx-meta" style="display:block">${date(t.createdAt)}${t.counterpartyNumber?' · '+masked(t.counterpartyNumber):' · Savings account'}</span></span><span class="tx-value ${t.amount>0?'in':''}">${t.amount>0?'+':'−'}${money(Math.abs(t.amount))}<small>Completed</small></span></button>`).join('')}</div>`:empty(); }
const titles={dashboard:'Dashboard',account:'My account',deposit:'Deposit funds',withdraw:'Withdraw funds',transfer:'Transfer money',transactions:'Transactions',profile:'My profile',customers:'Customers',accounts:'Accounts',customer:'Customer details'};
function shell(route,body,subtitle='') {
 const admin=state.user.role==='ADMIN', active=route==='customer'?'customers':['deposit','withdraw'].includes(route)?'account':route;
 const nav=admin?[['dashboard','layout-dashboard','Overview'],['customers','users-round','Customers'],['accounts','wallet-cards','Accounts'],['transactions','arrow-left-right','Transactions'],['profile','user-round','Profile']]:[['dashboard','layout-dashboard','Dashboard'],['account','wallet-cards','My account'],['transfer','arrow-left-right','Transfer'],['transactions','receipt-text','Transactions'],['profile','user-round','Profile']];
 const h=titles[route]||'Dashboard';
 const markup=`<div class="workspace" data-route="${route}" data-role="${state.user.role}"><header class="navigation-panel"><div class="navigation-brand-row">${brand()}<a href="#profile" class="mobile-greeting" aria-label="Your profile"><span class="avatar">${initials(state.user)}</span><span><strong>Hi, ${esc(state.user.firstName.split(' ')[0])}</strong><small>Welcome back!</small></span></a><a href="#dashboard" class="mobile-back icon-btn" aria-label="Back to dashboard">${icon('arrow-left')}</a><span class="mobile-page-title">${h}</span><div class="navigation-tools"><span class="sim-label">${icon('shield-check')} Simulated banking</span><a class="icon-btn nav-search" href="#transactions" aria-label="Search history" title="Search history">${icon('search')}</a><a href="#profile" class="user-chip" aria-label="Open profile"><span class="avatar">${initials(state.user)}</span><div><strong>${esc(state.user.firstName.split(' ')[0])} ${esc(state.user.lastName)}</strong><small>${admin?'Administrator':'Personal account'}</small></div></a><button class="icon-btn nav-logout" data-action="logout" aria-label="Log out" title="Log out">${icon('log-out')}</button></div></div><nav class="app-navigation" aria-label="Main navigation">${nav.map(([url,ic,name])=>`<a href="#${url}" class="${active===url?'active':''}" ${active===url?'aria-current="page"':''}><span class="nav-icon">${icon(ic)}</span><span class="nav-text">${name}</span></a>`).join('')}</nav></header><main class="content"><div class="page-heading"><div><span class="page-eyebrow">${admin?'VELISBANK / ADMINISTRATION':'YOUR EVERYDAY, ELEVATED'}</span><h1>${route==='dashboard'?(admin?'Bank overview':`${greeting()}, <span class="gradient-text">${esc(state.user.firstName.split(' ')[0])}</span>`):h}</h1><p>${subtitle}</p></div><div class="date-chip">${icon('calendar-days')}${date(new Date())}</div></div>${body}<footer class="footer"><span>© ${new Date().getFullYear()} VelisBank · Your everyday, elevated.</span><span>${icon('lock-keyhole')} A simulated banking experience</span></footer></main></div>`;
 const existing=app.querySelector('.workspace');
 if(existing) {
   const template=document.createElement('template');template.innerHTML=markup;
   existing.dataset.route=route;existing.dataset.role=state.user.role;
   existing.querySelector('.mobile-greeting').replaceWith(template.content.querySelector('.mobile-greeting'));
   existing.querySelector('.mobile-page-title').textContent=h;
   existing.querySelector('.user-chip').replaceWith(template.content.querySelector('.user-chip'));
   existing.querySelector('.content').replaceWith(template.content.querySelector('.content'));
   existing.querySelectorAll('.app-navigation a').forEach(link=>{const selected=link.hash==='#'+active;link.classList.toggle('active',selected);if(selected)link.setAttribute('aria-current','page');else link.removeAttribute('aria-current');});
 } else app.innerHTML=markup;
 document.body.classList.remove('is-loading');app.removeAttribute('aria-busy');
 syncNavigation();renderIcons();document.title=`${h} · VelisBank`;
}
function syncNavigation() {
 const w=app.querySelector('.workspace');if(!w)return;
 const navigation=w.querySelector('.app-navigation'),mobile=matchMedia('(max-width:650px)').matches;
 const parent=mobile?w:w.querySelector('.navigation-panel');if(navigation.parentElement!==parent)parent.append(navigation);
 let active=w.dataset.route;if(active==='customer')active='customers';if(['deposit','withdraw'].includes(active)||(active==='transfer'&&matchMedia('(max-width:650px)').matches))active='account';
 w.querySelectorAll('.app-navigation a').forEach(a=>{const selected=a.hash==='#'+active;a.classList.toggle('active',selected);if(selected)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});
}
matchMedia('(max-width:650px)').addEventListener('change',syncNavigation);
function greeting() { const h=new Date().getHours();return h<12?'Good morning':h<18?'Good afternoon':'Good evening'; }
function dashboard() {
 const a=state.account;
 shell('dashboard',`${frozen(a)}<div class="dashboard-grid"><div class="stack">${balanceCard(a)}<div class="quick-actions">${[['deposit','landmark','Deposit','Add funds'],['withdraw','banknote','Withdraw','Take funds'],['transfer','arrow-left-right','Transfer','Send funds']].map(([path,ic,title,desc])=>`<button class="action-card" data-go="${path}" ${a.status==='FROZEN'?'disabled':''}><span class="action-icon">${icon(ic)}</span><span><strong>${title}</strong><small>${desc}</small></span></button>`).join('')}</div><section class="card"><div class="card-head"><h2><a href="#transactions" class="heading-link">Recent transactions</a></h2><a class="text-btn" href="#transactions">View all ${icon('arrow-up-right')}</a></div>${transactionRows(state.transactions.slice(0,5))}</section></div><div class="stack"><section class="card insight-card destination-card">${icon('sprout')}<h2>A little clarity.<br>A lot of peace of mind.</h2><p>Keep an eye on your balance and stay in control of your everyday banking.</p><a href="#transactions" class="text-btn card-destination">Explore your activity ${icon('arrow-up-right')}</a></section></div></div>`,"Here’s a little overview of your finances today.");
}
function accountPage() {
 const a=state.account,rows=state.transactions;
 const incoming=rows.reduce((sum,t)=>sum+Math.max(0,Number(t.amount)),0),outgoing=rows.reduce((sum,t)=>sum+Math.max(0,-Number(t.amount)),0);
 shell('account',`${frozen(a)}<div class="account-layout"><div class="stack">${balanceCard(a)}<div class="quick-actions">${[['deposit','landmark','Deposit'],['withdraw','banknote','Withdraw'],['transfer','arrow-left-right','Transfer']].map(([path,ic,title])=>`<button class="action-card" data-go="${path}" ${a.status==='FROZEN'?'disabled':''}><span class="action-icon">${icon(ic)}</span><strong>${title}</strong></button>`).join('')}</div><section class="account-pulse"><div class="card-head"><h2>Account activity</h2><a href="#transactions" aria-label="View account activity">${icon('arrow-up-right')}</a></div><div class="account-flow"><a href="#transactions"><span>${icon('arrow-down-left')} Money in</span><strong>${money(incoming)}</strong></a><a href="#transactions"><span>${icon('arrow-up-right')} Money out</span><strong>${money(outgoing)}</strong></a></div><small>All recorded activity · ${rows.length} transactions</small></section></div><div class="stack"><section class="card account-tools"><h2>Manage your account</h2><a href="#profile"><span class="tool-symbol">${icon('user-round')}</span><span><strong>Personal details</strong><small>Keep your profile up to date</small></span>${icon('chevron-right')}</a><a href="#profile"><span class="tool-symbol security">${icon('shield-check')}</span><span><strong>Security</strong><small>Manage your PIN and mobile verification</small></span>${icon('chevron-right')}</a><a href="#transactions"><span class="tool-symbol activity">${icon('receipt-text')}</span><span><strong>Transaction history</strong><small>Review your account activity</small></span>${icon('chevron-right')}</a></section><section class="card account-recent"><div class="card-head"><h2>Latest activity</h2><a href="#transactions" class="text-btn">View all</a></div>${transactionRows(rows.slice(0,3))}</section></div></div>`,'Your account, activity and everyday controls.');
}
function landing() {
 app.innerHTML=`<div class="landing"><header class="public-nav">${brand()}<div><a href="#login">Log in</a><a class="btn" href="#register">Open an account ${icon('arrow-up-right')}</a></div></header><main><section class="hero"><div><span class="eyebrow">${icon('sprout')} A simpler way to bank</span><h1>Your money.<br>Your everyday.<br><em>Made simple.</em></h1><p>A little less complexity. A little more clarity. Manage your simulated finances in one thoughtfully simple space.</p><div class="hero-actions"><a class="btn" href="#register">Open an account ${icon('arrow-up-right')}</a><a class="btn secondary" href="#login">Log in</a></div><span class="hero-note">${icon('shield-check')} Simulated funds. Real learning.</span></div><div class="hero-art">${balanceCard({balance:12500,status:'ACTIVE',number:'1029384752'},true)}<div class="hero-mini"><span class="tx-icon">${icon('landmark')}</span><span><strong>Deposit completed</strong><small>Every little step adds up.</small></span><b>+₱2,000</b></div><p class="sample-caption">An illustration of your future dashboard.</p></div></section><section class="features"><article class="card feature"><span class="action-icon">${icon('shield-check')}</span><h2><a class="card-destination" href="#register">A space that’s yours</a></h2><p>Your own account, protected by secure authentication. Everything starts with you.</p></article><article class="card feature"><span class="action-icon">${icon('arrow-left-right')}</span><h2><a class="card-destination" href="#login">Move money, simply</a></h2><p>Deposit, withdraw, and transfer simulated funds to other VelisBank accounts.</p></article><article class="card feature"><span class="action-icon">${icon('receipt-text')}</span><h2><a class="card-destination" href="#login">See the whole picture</a></h2><p>Clear balances and a record of every transaction. Know where things stand.</p></article></section></main><footer class="landing-foot">© ${new Date().getFullYear()} VelisBank · A simulated banking application. No real money is held or transferred.</footer></div>`;renderIcons();
}
function authLayout(body) {app.innerHTML=`<div class="auth-page"><aside class="auth-aside">${brand()}<h1>Banking that fits<br>your <span>everyday.</span></h1><p>A simple, thoughtful space for your finances. Your next chapter starts here.</p><div class="auth-bottom">${icon('shield-check')} Simulated funds. Real learning.</div></aside><main class="auth-main"><div class="auth-card"><a class="back-link" href="#home">${icon('arrow-left')} Back to VelisBank</a>${body}</div></main></div>`;renderIcons();}
let loginTimer;
function adminLogin(message='') {
 clearInterval(loginTimer);
 authLayout(`<h1 class="login-title">Admin login</h1>${message?`<div class="warning">${esc(message)}</div>`:''}<form id="login-form"><div class="form-error" role="alert"></div>${field('username','Username','text','',{autocomplete:'username',max:30})}${field('password','Password','password','',{autocomplete:'current-password'})}<button class="btn full" type="submit">Log in ${icon('arrow-right')}</button></form><p class="auth-link"><button type="button" class="text-btn" id="customer-login">Back to customer login</button></p>`);
 document.getElementById('customer-login').onclick=()=>{location.hash='login';};
 const loginForm=document.getElementById('login-form');
 const storageKey=()=> 'velisbank-login-until:'+loginForm.elements.username.value.trim().toLowerCase();
 let cooldowns={};try{cooldowns=JSON.parse(localStorage.getItem('velisbank-login-cooldowns')||'{}');}catch{}
 const updateCooldown=()=>{if(!loginForm.isConnected){clearInterval(loginTimer);return;}const seconds=Math.max(0,Math.ceil(((Number(cooldowns[storageKey()])||0)-Date.now())/1000));const button=loginForm.querySelector('[type=submit]');if(seconds){button.disabled=true;button.textContent=`Try again in ${Math.floor(seconds/60)}:${String(seconds%60).padStart(2,'0')}`;loginForm.dataset.cooling='true';}else if(loginForm.dataset.cooling){delete loginForm.dataset.cooling;button.disabled=false;button.textContent='Log in';loginForm.querySelector('.form-error').textContent='You can try logging in again.';}};
 loginForm.elements.username.addEventListener('input',updateCooldown);loginTimer=setInterval(updateCooldown,1000);updateCooldown();
 loginForm.onsubmit=async e=>{e.preventDefault();updateCooldown();if(loginForm.dataset.cooling)return;const attemptKey=storageKey();const form=e.currentTarget,button=form.querySelector('[type=submit]');button.disabled=true;button.textContent='Logging in…';try {await api('/login',{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded'},body:new URLSearchParams(new FormData(form))});await csrf();state.user=await api('/me');state.reveal=false;location.hash='dashboard';}catch(err){errors(form,err);button.disabled=false;button.textContent='Log in';if(err.attemptsRemaining!==undefined){form.querySelector('.form-error').textContent=`Incorrect username or password. ${err.attemptsRemaining} attempt${err.attemptsRemaining===1?'':'s'} remaining before a 5-minute cooldown.`;}if(err.status===429){cooldowns[attemptKey]=Date.now()+Number(err.retryAfterSeconds||300)*1000;try{localStorage.setItem('velisbank-login-cooldowns',JSON.stringify(cooldowns));}catch{}updateCooldown();}}};
}
function registration() {
 authLayout(`<h1>Join VelisBank.</h1><p>Your mobile number is your login. No username or password needed.</p><form id="register-form"><div class="form-error" role="alert"></div><div class="form-grid">${field('firstName','First name','text','',{max:60})}${field('lastName','Last name','text','',{max:60})}${field('phone','Mobile number','tel','',{max:24,autocomplete:'tel',hint:'Philippines · 09XX XXX XXXX'})}${field('email','Email address','email','',{max:160})}</div>${field('address','Address','text','',{max:240})}<button class="btn full" type="submit">Create account</button></form><p class="auth-link">Already registered? <a href="#login">Log in</a></p>`);
 document.getElementById('register-form').onsubmit=async e=>{e.preventDefault();const f=e.currentTarget,b=f.querySelector('[type=submit]'),values=formValues(f);b.disabled=true;try{await api('/mobile/register',{method:'POST',body:JSON.stringify(values)});state.pendingPhone=values.phone;state.loginMessage='Account created. Verify your mobile number to continue.';location.hash='login';}catch(err){errors(f,err);b.disabled=false;}};
}
function login(message='') { mobileLogin(message,state.pendingPhone||'');state.pendingPhone=''; }
function mobileLogin(message='',phone='',purpose='LOGIN') {
 clearInterval(loginTimer);
 authLayout(`<div class="mobile-auth-brand">${brand()}</div><h1 class="login-title">${purpose==='RESET'?'Reset PIN':'Log in'}</h1>${message?`<div class="warning">${esc(message)}</div>`:''}<form id="mobile-login-form"><div class="form-error" role="alert"></div>${field('phone','Mobile number','tel',phone,{max:24,autocomplete:'tel',hint:'09XX XXX XXXX or +63 9XX XXX XXXX'})}<button class="btn full" type="submit">Continue ${icon('arrow-right')}</button></form><div class="auth-links"><button class="text-btn" id="forgot-pin">${purpose==='RESET'?'Back to login':'Forgot PIN?'}</button><a href="#register">Create account</a></div>`);
 const f=document.getElementById('mobile-login-form');f.onsubmit=async e=>{e.preventDefault();const b=f.querySelector('[type=submit]');b.disabled=true;try{const phone=f.elements.phone.value;const result=await api('/mobile/otp',{method:'POST',body:JSON.stringify({phone,purpose})});otpScreen(phone,purpose,result);}catch(err){errors(f,err);b.disabled=false;}};
 document.getElementById('forgot-pin').onclick=()=>mobileLogin('',f.elements.phone.value,purpose==='RESET'?'LOGIN':'RESET');
}
function otpScreen(phone,purpose,result) {
 clearInterval(loginTimer);
 authLayout(`<section class="otp-confirmation"><h1>Confirmation</h1><div class="otp-illustration" aria-hidden="true"><svg viewBox="0 0 120 110" fill="none"><rect x="20" y="26" width="43" height="75" rx="9" stroke="currentColor" stroke-width="2.5"/><path d="M20 83h43M32 34h12" stroke="currentColor" stroke-width="2.5"/><circle cx="42" cy="92" r="2" fill="currentColor"/><path d="M59 12h42a7 7 0 0 1 7 7v23a7 7 0 0 1-7 7H79L67 61V49h-8a7 7 0 0 1-7-7V19a7 7 0 0 1 7-7Z" fill="#f9faff" stroke="currentColor" stroke-width="2.5"/><path d="M64 30h1m9 0h1m9 0h1m9 0h1" stroke="currentColor" stroke-width="3" stroke-linecap="round"/></svg><img src="/favicon.svg" alt="" width="26" height="26"></div><p class="otp-instruction">${result.localTest?'Enter the 6-digit test code for':'Enter the 6-digit code sent to'}<br><strong>${esc(phone)}</strong></p><form id="otp-form"><label class="otp-label" for="otp-code">Verification code</label><input id="otp-code" name="code" class="otp-code" inputmode="numeric" autocomplete="one-time-code" pattern="[0-9]{6}" maxlength="6" required aria-describedby="otp-countdown"><div class="form-error" role="alert"></div><button class="btn full" type="submit">Next</button></form><div class="otp-resend"><button class="text-btn" id="resend-code" disabled>Resend code</button><span id="otp-countdown" role="timer"></span></div>${result.localTest?'<small class="otp-local-note">Local test · Code in application log</small>':''}<button class="text-btn otp-change" id="change-number">Change number</button></section>`);
 const f=document.getElementById('otp-form'),resend=document.getElementById('resend-code');const update=()=>{if(!f.isConnected){clearInterval(loginTimer);return;}const left=Math.max(0,Math.ceil((Date.parse(result.expiresAt)-Date.now())/1000));document.getElementById('otp-countdown').textContent=left?`Time remaining 00:${String(left).padStart(2,'0')}`:'00:00 — Resend code';resend.disabled=left>0;if(!left)f.querySelector('[type=submit]').disabled=true;};update();loginTimer=setInterval(update,1000);
 const otpInput=f.elements.code,slots=document.createElement('div'),otpWrap=document.createElement('div');
 otpWrap.className='otp-box-entry';slots.className='otp-boxes';slots.setAttribute('aria-hidden','true');slots.innerHTML='<span></span>'.repeat(6);
 otpInput.before(otpWrap);otpWrap.append(otpInput,slots);
 otpInput.oninput=()=>{otpInput.value=otpInput.value.replace(/\D/g,'').slice(0,6);slots.querySelectorAll('span').forEach((slot,i)=>{slot.textContent=otpInput.value[i]||'';slot.classList.toggle('filled',i<otpInput.value.length);slot.classList.toggle('current',i===otpInput.value.length);});};otpInput.oninput();

 f.onsubmit=async e=>{e.preventDefault();const b=f.querySelector('[type=submit]');b.disabled=true;try{const grant=await api('/mobile/verify',{method:'POST',body:JSON.stringify({phone,purpose,code:f.elements.code.value})});clearInterval(loginTimer);mobilePin(grant.createPin);}catch(err){errors(f,err);b.disabled=false;update();}};
 resend.onclick=async()=>{resend.disabled=true;try{otpScreen(phone,purpose,await api('/mobile/otp',{method:'POST',body:JSON.stringify({phone,purpose})}));}catch(err){errors(f,err);resend.disabled=false;}};
 document.getElementById('change-number').onclick=()=>mobileLogin('',phone,purpose);
}
function mobilePin(create) {
 authLayout('<h1>Mobile verified.</h1><p>Complete PIN verification to open your account.</p>');
 const finish=async(pin,confirmPin)=>{await api('/mobile/complete',{method:'POST',body:JSON.stringify({pin,confirmPin})});modalBusy=false;closeModal();await csrf();state.user=await api('/me');state.reveal=false;if(location.hash==='#dashboard')await renderRoute();else location.hash='dashboard';};
 const choose=()=>pinKeypad(create?'Create your PIN':'Enter your PIN',create?'Choose six digits to protect login and transactions.':'Enter your six-digit VelisBank PIN.',async pin=>{if(!create)return finish(pin,null);pinKeypad('Confirm your PIN','Enter the same six digits again.',async confirmation=>{if(pin!==confirmation)throw {message:'PINs do not match. Try again.'};await finish(pin,confirmation);},{back:choose});},{back:()=>{closeModal();mobileLogin();}});choose();
}
function moneySteps(active) {
 return `<ol class="money-steps" aria-label="Transaction progress">${['Enter details','Verify PIN','Review & confirm'].map((text,i)=>`<li ${active===i+1?'aria-current="step"':''} class="${i+1<=active?'reached':''}"><span>${i+1}</span>${text}</li>`).join('')}</ol>`;
}
function pinKeypad(title,description,onComplete,{progress='',back=null}={}) {
 modal(title,`${progress}<form id="keypad-form" class="pin-screen"><span class="pin-emblem"><img src="/favicon.svg" alt="VelisBank" width="58" height="58"></span><h3>${title}</h3><p>${description}</p><label class="pin-entry-label" for="keypad-value">Six-digit PIN</label><input id="keypad-value" class="pin-entry" type="password" inputmode="numeric" autocomplete="off" maxlength="6" minlength="6" pattern="[0-9]{6}" required aria-describedby="keypad-error"><div class="pin-dots" aria-hidden="true">${'<span></span>'.repeat(6)}</div><div id="keypad-error" class="form-error" role="alert"></div><div class="pin-keypad">${['1','2','3','4','5','6','7','8','9','clear','0','delete'].map(k=>`<button type="button" data-pin-key="${k}" aria-label="${k==='delete'?'Delete last digit':k==='clear'?'Clear PIN':k}">${k==='delete'?icon('delete'):k==='clear'?icon('rotate-ccw'):k}</button>`).join('')}</div><button class="btn full" type="submit" disabled>Continue</button>${back?'<button class="text-btn pin-back" type="button" id="pin-back">Back</button>':''}<a href="#profile" data-action="pin-profile" class="pin-help">Manage PIN in Profile</a></form>`);
 const f=document.getElementById('keypad-form'),input=f.querySelector('input'),submit=f.querySelector('[type=submit]');
 let revealPin=false;
 const visibility=document.createElement('button');visibility.type='button';visibility.className='text-btn pin-visibility';visibility.setAttribute('aria-pressed','false');
 f.querySelector('.pin-dots').after(visibility);
 const sync=()=>{input.value=input.value.replace(/\D/g,'').slice(0,6);f.querySelectorAll('.pin-dots span').forEach((dot,i)=>{dot.classList.toggle('filled',i<input.value.length);dot.textContent=i<input.value.length?(revealPin?input.value[i]:'•'):'';});submit.disabled=input.value.length!==6;visibility.innerHTML=icon('eye')+(revealPin?'Hide PIN':'Show PIN');visibility.setAttribute('aria-pressed',String(revealPin));renderIcons();};
 visibility.onclick=()=>{revealPin=!revealPin;sync();renderIcons();};sync();renderIcons();
 input.oninput=sync;f.querySelectorAll('[data-pin-key]').forEach(b=>b.onclick=()=>{const k=b.dataset.pinKey;input.value=k==='clear'?'':k==='delete'?input.value.slice(0,-1):(input.value+k).slice(0,6);sync();});
 if(back)document.getElementById('pin-back').onclick=back;
 f.onsubmit=async event=>{event.preventDefault();if(input.value.length!==6)return;const value=input.value;modalBusy=true;f.querySelectorAll('button,input').forEach(el=>el.disabled=true);try{await onComplete(value);}catch(err){if(f.isConnected){document.getElementById('keypad-error').textContent=err.message||'Please try again.';input.value='';f.querySelectorAll('button,input').forEach(el=>el.disabled=false);sync();input.focus();}}finally{modalBusy=false;}};
}
function setupPin() { closeModal(); mobileLogin('',state.user?.phone||'','RESET'); }
function verifyTransactionPin(payload,form) {
 pinKeypad('Enter your PIN','Verify your identity before reviewing this transaction.',async pin=>{const review=await api('/money/verify-pin',{method:'POST',body:JSON.stringify({...payload,pin})});confirmMoney({...payload,pin},review,form);},{progress:moneySteps(2),back:()=>closeModal()});
}

function moneyPage(route) {
 const type={deposit:'DEPOSIT',withdraw:'WITHDRAWAL',transfer:'TRANSFER'}[route],verb={deposit:'Deposit',withdraw:'Withdraw',transfer:'Transfer'}[route],a=state.account;
 shell(route,`${frozen(a)}<div class="two-col"><div class="stack">${balanceCard(a)}<section class="card"><h2 style="margin-bottom:12px">${route==='transfer'?'A moment to double-check.':'Simple steps. Clear feedback.'}</h2><p class="muted" style="font-size:12px">${route==='transfer'?'Enter the recipient’s full 10-digit VelisBank account number. You’ll review their name and the amount before sending.':'Enter an amount, review the details, and confirm. Your updated balance and receipt will appear after completion.'}</p><div class="info-foot">${icon('info')} All funds in VelisBank are simulated.</div></section></div><section class="card form-card">${moneySteps(1)}<h2>${verb==='Transfer'?'Send money':verb+' funds'}</h2><p>${verb==='Transfer'?'A simple transfer to another VelisBank account.':'Manage your savings, one step at a time.'}</p><form id="money-form"><div class="form-error" role="alert"></div>${route==='transfer'?field('recipient','Recipient account number','text','',{max:10,min:10,pattern:'[0-9]{10}',placeholder:'Enter 10-digit account number'}):''}<div class="field"><label for="field-amount">Amount</label><div class="input-wrap amount-input"><span>₱</span><input id="field-amount" type="number" name="amount" min="0.01" max="999999999.99" step="0.01" inputmode="decimal" placeholder="0.00" required aria-describedby="error-amount"></div><span class="field-error" id="error-amount"></span></div>${route==='transfer'?field('description','Description <span class="muted">(optional)</span>','textarea','',{optional:true,max:140,placeholder:'What is this transfer for?'}):''}<button class="btn full" type="submit" ${a.status==='FROZEN'?'disabled':''}>Continue ${icon('arrow-right')}</button></form></section></div>`,route==='transfer'?'Send a little something, with confidence.':`Your ${route==='deposit'?'next deposit':'withdrawal'}, made simple.`);
 document.getElementById('money-form').onsubmit=async e=>{e.preventDefault();const f=e.currentTarget,b=f.querySelector('[type=submit]');b.disabled=true;b.classList.add('is-processing');b.textContent='Checking details…';const values=formValues(f),payload={...values,type,amount:values.amount,requestKey:crypto.randomUUID()};try{await api('/money/review',{method:'POST',body:JSON.stringify(payload)});if(!state.pinConfigured){setupPin(()=>verifyTransactionPin(payload,f));}else verifyTransactionPin(payload,f);}catch(err){errors(f,err);}finally{b.disabled=false;b.classList.remove('is-processing');b.innerHTML=`Continue ${icon('arrow-right')}`;renderIcons();}};
}
let modalPreviousFocus, modalBusy=false;
function modal(title,body) {
 if(!overlay.firstChild)modalPreviousFocus=document.activeElement;
 overlay.innerHTML=`<div class="modal-backdrop"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="modal-title"><div class="modal-head"><h2 id="modal-title">${title}</h2><button class="icon-btn" data-action="close-modal" aria-label="Close dialog">${icon('x')}</button></div>${body}</section></div>`;
 app.inert=true;document.body.style.overflow='hidden';renderIcons();
 (overlay.querySelector('input,textarea')||overlay.querySelector('button'))?.focus();
}
function closeModal(animate=false) {
 if(modalBusy)return;
 const root=overlay.firstChild;
 const finish=()=>{if(root&&overlay.firstChild!==root)return;overlay.innerHTML='';app.inert=false;document.body.style.overflow='';if(modalPreviousFocus?.isConnected)modalPreviousFocus.focus();};
 if(animate&&root&&!matchMedia('(prefers-reduced-motion: reduce)').matches){root.classList.add('is-closing');setTimeout(finish,170);}else finish();
}
function confirmMoney(payload,review,form) {
 modal(`Confirm ${label(payload.type).toLowerCase()}`,`${moneySteps(3)}<div class="receipt-hero"><p>You’re about to ${payload.type==='TRANSFER'?'send':payload.type==='DEPOSIT'?'deposit':'withdraw'}</p><div class="receipt-amount">${money(payload.amount)}</div></div><div class="receipt-details">${info([...(review.recipientName?[['Recipient',esc(review.recipientName)],['Account',masked(review.recipientNumber)]]:[['Account',masked(state.account.number)]]),['Description',esc(payload.description||'—')]])}</div><div class="form-error" id="confirm-error" role="alert" style="margin-top:15px"></div><div class="form-actions"><button class="btn secondary" data-action="close-modal">Back</button><button class="btn" id="confirm-money">Confirm ${label(payload.type).toLowerCase()}</button></div>`);

 document.getElementById('confirm-money').onclick=async()=>{const b=document.getElementById('confirm-money');modalBusy=true;overlay.querySelectorAll('button').forEach(el=>el.disabled=true);b.textContent='Processing…';try{const result=await api('/money',{method:'POST',body:JSON.stringify(payload)});modalBusy=false;state.account.balance=result.balanceAfter;receipt(result,true);if(form)form.reset();const displayed=document.querySelector('.balance-value');if(displayed)displayed.textContent=money(result.balanceAfter);}catch(err){document.getElementById('confirm-error').textContent=err.message;modalBusy=false;overlay.querySelectorAll('button').forEach(el=>el.disabled=false);const pinInput=document.getElementById('field-pin');if(pinInput){pinInput.value='';pinInput.focus();}b.textContent='Try again';}};
}
function receipt(t,success=false) {
 const title=success?`${t.type==='TRANSFER_OUT'?'Transfer':label(t.type)} successful`:'Transaction details';
 modal(title,`<div class="receipt-hero"><div class="receipt-icon">${icon('circle-check')}</div><h2>${success?'All done. You’re all set.':'A clear record, every time.'}</h2><div class="receipt-amount">${t.amount>0?'+':'−'}${money(Math.abs(t.amount))}</div>${badge('COMPLETED')}</div><div class="receipt-details">${info([['Type',label(t.type)],...(t.counterpartyName?[[t.amount<0?'To':'From',esc(t.counterpartyName)],['Account',masked(t.counterpartyNumber)]]:[]),['Balance after',money(t.balanceAfter)],['Reference',esc(t.reference)],['Date',date(t.createdAt,true)],['Description',esc(t.description||'—')]])}</div>${success?'<button class="btn full" id="receipt-done">Back to dashboard</button>':''}`);
 if(success)document.getElementById('receipt-done').onclick=()=>{closeModal();if(location.hash==='#dashboard')renderRoute();else location.hash='dashboard';};
}
function transactionsPage() {
 const rows=state.transactions, incoming=rows.filter(t=>t.amount>0).reduce((n,t)=>n+Number(t.amount),0),outgoing=rows.filter(t=>t.amount<0).reduce((n,t)=>n-Number(t.amount),0);
 shell('transactions',`<div class="summary-grid"><section class="card"><div class="stat-label">Money in ${icon('arrow-down-left')}</div><div class="stat-value" style="color:var(--green)">${money(incoming)}</div><div class="stat-foot">All incoming activity</div></section><section class="card"><div class="stat-label">Money out ${icon('arrow-up-right')}</div><div class="stat-value">${money(outgoing)}</div><div class="stat-foot">All outgoing activity</div></section></div><section class="card history-card"><div class="card-head"><h2>Your activity</h2><span class="small muted">${rows.length} records</span></div><div class="filter-bar">${filters()}<input class="search-input" id="history-search" placeholder="Search history…" aria-label="Search transactions"></div><div id="history-rows"></div></section>`, 'Every transaction, a little more clarity.');
 bindFilters(()=>{let filtered=filterTransactions(rows);document.getElementById('history-rows').innerHTML=filtered.length?transactionRows(filtered):empty('Nothing to show here','Try a different filter or search.');renderIcons();});
}
function filters() {return `<div class="filters" aria-label="Transaction type">${[['ALL','All activity'],['DEPOSIT','Deposits'],['WITHDRAWAL','Withdrawals'],['TRANSFER','Transfers']].map(([type,name])=>`<button class="filter ${state.filter===type?'active':''}" data-filter="${type}" aria-pressed="${state.filter===type}">${name}</button>`).join('')}</div>`;}
function filterTransactions(rows) {return rows.filter(t=>(state.filter==='ALL'||t.type.startsWith(state.filter))&&[t.reference,t.accountNumber,t.description,t.counterpartyName,t.counterpartyNumber].join(' ').toLowerCase().includes(state.search.toLowerCase()));}
function bindFilters(update) {state.search='';document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{state.filter=b.dataset.filter;document.querySelectorAll('[data-filter]').forEach(el=>{el.classList.toggle('active',el===b);el.setAttribute('aria-pressed',String(el===b));});update();});document.getElementById('history-search').oninput=e=>{state.search=e.target.value;update();};update();}
function profilePage() {
 const p=state.user;
 shell('profile',`<div class="two-col"><section class="card"><div class="profile-heading"><span class="avatar large">${initials(p)}</span><div><h2>${esc(fullName(p))}</h2><p>${p.role==='ADMIN'?'Administrator · @'+esc(p.username):'Personal account'}</p></div></div>${info([['Email',esc(p.email)],['Phone',esc(p.phone)],['Address',esc(p.address)],['Member since',date(p.createdAt)]])}<button class="btn secondary" style="margin-top:28px" id="edit-profile">${icon('pencil')} Edit profile</button></section><section class="card"><div class="card-head"><h2>Security</h2>${icon('shield-check')}</div>${p.role==='ADMIN'?`${info([['Password','••••••••••••']])}<p class="muted" style="font-size:11px;margin-top:22px">A strong password helps keep your account yours. Update it whenever you need.</p><button class="btn secondary" style="margin-top:22px" id="change-password">Change password</button>`:''}${p.role==='CUSTOMER'?`<div class="pin-settings"><span class="tool-symbol security">${icon('key-round')}</span><h2>Transaction PIN</h2><p class="muted">${state.pinConfigured?'Your transaction PIN is ready.':'Set up a six-digit PIN to start making transactions.'}</p><button class="btn secondary" data-action="setup-pin">${state.pinConfigured?'Reset PIN':'Set up PIN'}</button></div>`:''}</section></div>`,'A space for your details and peace of mind.');
 document.getElementById('edit-profile').onclick=()=>{modal('Edit your profile',`<form id="profile-form"><div class="form-error" role="alert"></div><div class="form-grid">${field('firstName','First name','text',p.firstName,{max:60})}${field('lastName','Last name','text',p.lastName,{max:60})}</div><div style="margin-top:18px">${field('email','Email','email',p.email,{max:160})}${field('phone','Phone','tel',p.phone,{max:20})}${field('address','Address','textarea',p.address,{max:240})}</div><button class="btn full" type="submit">Save changes</button></form>`);document.getElementById('profile-form').onsubmit=async e=>{e.preventDefault();const f=e.currentTarget,b=f.querySelector('[type=submit]');b.disabled=true;try{state.user=await api('/profile',{method:'PUT',body:JSON.stringify(formValues(f))});closeModal();profilePage();toast('Your profile has been updated.');}catch(err){errors(f,err);b.disabled=false;}};};
 if(document.getElementById('change-password'))document.getElementById('change-password').onclick=()=>{modal('Change password',`<form id="password-form"><div class="form-error" role="alert"></div>${field('currentPassword','Current password','password','',{autocomplete:'current-password'})}${field('password','New password','password','',{min:10,max:64,autocomplete:'new-password'})}${field('confirmPassword','Confirm new password','password','',{min:10,max:64,autocomplete:'new-password'})}<p class="field-hint">Use 10–64 characters and a password different from your current one. You’ll log in again after saving.</p><button class="btn full" type="submit">Update password</button></form>`);document.getElementById('password-form').onsubmit=async e=>{e.preventDefault();const f=e.currentTarget,b=f.querySelector('[type=submit]');b.disabled=true;try{await api('/password',{method:'PUT',body:JSON.stringify(formValues(f))});closeModal();state.user=null;await csrf();location.hash='login';toast('Password updated. Log in with your new password.');}catch(err){errors(f,err);b.disabled=false;}};};
}
function adminDashboard() {
 const as=state.accounts,ts=state.adminTransactions,stats=[['Customers',as.length,'Registered customers','users-round'],['Active accounts',as.filter(a=>a.status==='ACTIVE').length,'Ready for everyday banking','wallet-cards'],['Frozen accounts',as.filter(a=>a.status==='FROZEN').length,'Temporarily restricted','snowflake'],['Transactions',new Set(ts.map(t=>t.reference)).size,'Completed operations','arrow-left-right']];
 shell('dashboard',`<div class="stat-grid">${stats.map(([title,note,desc,ic],index)=>`<section class="card destination-card"><a class="stat-link" href="#${['customers','accounts/ACTIVE','accounts/FROZEN','transactions'][index]}" aria-label="View ${title.toLowerCase()}"></a><div class="stat-label">${title}${icon(ic)}</div><div class="stat-value">${note.toLocaleString()}</div><div class="stat-foot">${desc}</div></section>`).join('')}</div><div class="stack"><section class="card"><div class="card-head"><h2>Customer accounts</h2><a class="text-btn" href="#customers">View all ${icon('arrow-up-right')}</a></div>${accountsTable(as.slice(0,5))}</section><section class="card"><div class="card-head"><h2>Latest transactions</h2><a class="text-btn" href="#transactions">View all ${icon('arrow-up-right')}</a></div>${adminTransactionTable(ts.slice(0,5))}</section></div>`, 'A clear view of the people and activity at VelisBank.');
}
function accountsTable(accounts) {return accounts.length?`<div class="table-wrap"><table><thead><tr><th>Customer</th><th>Account</th><th>Balance</th><th>Status</th><th>Action</th></tr></thead><tbody>${accounts.map(a=>`<tr><td><div class="person-cell"><span class="avatar">${initials(a.customer)}</span><div>${esc(fullName(a.customer))}<div class="muted">${esc(a.customer.email)}</div></div></div></td><td>${masked(a.number)}</td><td>${money(a.balance)}</td><td>${badge(a.status)}</td><td><a class="text-btn" href="#customer/${a.id}">View ${icon('arrow-up-right')}</a></td></tr>`).join('')}</tbody></table></div>`:empty('No customers found','Registered customers will appear here.');}
function adminAccountsPage(route,initialStatus) {shell(route,`<section class="card"><div class="card-head"><h2>${route==='customers'?'Your customers':'All savings accounts'}</h2><span class="muted small">${state.accounts.length} accounts</span></div><div class="filter-bar"><input class="search-input" id="account-search" placeholder="Search name, username, email or account" aria-label="Search customers"><select id="status-filter" class="search-input" style="max-width:170px" aria-label="Account status"><option value="ALL">All statuses</option><option value="ACTIVE">Active</option><option value="FROZEN">Frozen</option></select></div><div id="account-rows">${accountsTable(state.accounts)}</div></section>`,'Find a customer, review their account, and manage its status.');const update=()=>{const q=document.getElementById('account-search').value.toLowerCase(),status=document.getElementById('status-filter').value;document.getElementById('account-rows').innerHTML=accountsTable(state.accounts.filter(a=>(status==='ALL'||a.status===status)&&[fullName(a.customer),a.customer.username,a.customer.email,a.number].join(' ').toLowerCase().includes(q)));renderIcons();};document.getElementById('account-search').oninput=update;document.getElementById('status-filter').onchange=update;if(['ACTIVE','FROZEN'].includes(initialStatus)){document.getElementById('status-filter').value=initialStatus;update();}}
function adminTransactionTable(rows) {return rows.length?`<div class="table-wrap"><table><thead><tr><th>Reference</th><th>Account</th><th>Type</th><th>Amount</th><th>Date</th><th>Details</th></tr></thead><tbody>${rows.map(t=>`<tr><td title="${esc(t.reference)}">${esc(t.reference.slice(0,12))}…</td><td>${masked(t.accountNumber)}</td><td>${label(t.type)}</td><td style="color:${t.amount>0?'var(--green)':'inherit'}">${t.amount>0?'+':'−'}${money(Math.abs(t.amount))}</td><td>${date(t.createdAt)}</td><td><button class="text-btn" data-admin-transaction="${t.id}">View ${icon('arrow-up-right')}</button></td></tr>`).join('')}</tbody></table></div>`:empty('No matching transactions','Try another filter or search.');}
function adminTransactionsPage() {shell('transactions',`<section class="card"><div class="card-head"><h2>Transaction records</h2><span class="muted small">${state.adminTransactions.length} ledger entries</span></div><div class="filter-bar">${filters()}<input class="search-input" id="history-search" placeholder="Search history…" aria-label="Search transactions"></div><div id="admin-tx-rows"></div></section>`,'Review deposits, withdrawals, and both sides of every transfer.');bindFilters(()=>{document.getElementById('admin-tx-rows').innerHTML=adminTransactionTable(filterTransactions(state.adminTransactions));renderIcons();});}
function customerDetail(a) {
 shell('customer',`<a href="#customers" class="back-link">${icon('arrow-left')} Back to customers</a><div class="two-col"><div class="stack"><section class="card"><div class="profile-heading"><span class="avatar large">${initials(a.customer)}</span><div><h2>${esc(fullName(a.customer))}</h2><p>@${esc(a.customer.username)}</p></div></div>${info([['Email',esc(a.customer.email)],['Phone',esc(a.customer.phone)],['Address',esc(a.customer.address)],['Member since',date(a.customer.createdAt)]])}</section><section class="card"><h2 style="margin-bottom:12px">Account management</h2><p class="muted" style="font-size:11px">${a.status==='ACTIVE'?'Freezing this account pauses deposits, withdrawals, and transfers. The customer can still view their account.':'Unfreezing this account restores deposits, withdrawals, and transfers.'}</p><button id="toggle-status" class="btn ${a.status==='ACTIVE'?'danger':''}" style="margin-top:20px">${icon(a.status==='ACTIVE'?'snowflake':'shield-check')} ${a.status==='ACTIVE'?'Freeze':'Unfreeze'} account</button></section></div><div class="stack">${balanceCard(a,true)}${accountInfo(a)}</div></div><section class="card" style="margin-top:24px"><div class="card-head"><h2>Customer activity</h2></div>${adminTransactionTable(state.adminTransactions.filter(t=>t.accountNumber===a.number))}</section>`,'Customer details and account controls, in one place.');
 document.getElementById('toggle-status').onclick=()=>{const verb=a.status==='ACTIVE'?'Freeze':'Unfreeze';modal(`${verb} account?`,`<p class="muted" style="font-size:12px;margin-bottom:22px">${verb==='Freeze'?'This customer will temporarily be unable to deposit, withdraw, or transfer funds.':'This customer will be able to deposit, withdraw, and transfer funds again.'}</p>${info([['Customer',esc(fullName(a.customer))],['Account',masked(a.number)]])}<div class="form-error" id="status-error" style="margin-top:15px" role="alert"></div><div class="form-actions"><button class="btn secondary" data-action="close-modal">Cancel</button><button id="confirm-status" class="btn ${verb==='Freeze'?'danger':''}">${verb} account</button></div>`);document.getElementById('confirm-status').onclick=async()=>{modalBusy=true;overlay.querySelectorAll('button').forEach(b=>b.disabled=true);try{await api(`/admin/accounts/${a.id}/status`,{method:'PATCH',body:JSON.stringify({status:a.status==='ACTIVE'?'FROZEN':'ACTIVE'})});modalBusy=false;closeModal();await renderRoute();toast(`Account ${verb==='Freeze'?'frozen':'unfrozen'}.`);}catch(err){modalBusy=false;document.getElementById('status-error').textContent=err.message;overlay.querySelectorAll('button').forEach(b=>b.disabled=false);}};};
}
async function renderRoute() {
 const version=++state.routeVersion;closeModal();const [route='home',id]=(location.hash.slice(1)||'home').split('/');
 document.title=`${titles[route]||'Banking, made simple'} · VelisBank`;
 if(['home','login','register','admin-login'].includes(route)) {if(state.user){location.hash='dashboard';return;}if(route==='home')landing();else if(route==='login'){login(state.loginMessage);state.loginMessage='';}else if(route==='admin-login'){adminLogin();document.title='Administration · VelisBank';}else registration();return;}
 if(!state.user){location.hash='login';return;}
 const loadingTimer=setTimeout(()=>{if(version===state.routeVersion){document.body.classList.add('is-loading');app.setAttribute('aria-busy','true');}},160);
 try {
  const session=await api('/session',{cache:'no-store'});if(version!==state.routeVersion)return;
  if(!session.authenticated){endSession();return;}state.user=session.user;
  if(state.user.role==='ADMIN') {
   const [accounts,transactions]=await Promise.all([api('/admin/accounts'),api('/admin/transactions')]);if(version!==state.routeVersion)return;state.accounts=accounts;state.adminTransactions=transactions;
   if(route==='dashboard')adminDashboard();else if(route==='customers'||route==='accounts')adminAccountsPage(route,id);else if(route==='transactions')adminTransactionsPage();else if(route==='profile')profilePage();else if(route==='customer'){const a=accounts.find(a=>a.id===Number(id));if(a)customerDetail(a);else shell('customer',empty('Account not found','Return to the customer list to choose an account.'));}else location.hash='dashboard';
  } else {
   const [account,transactions,pinStatus]=await Promise.all([api('/account'),api('/transactions'),api('/pin')]);state.pinConfigured=pinStatus.configured;if(version!==state.routeVersion)return;state.account=account;state.transactions=transactions;
   if(route==='dashboard')dashboard();else if(route==='account')accountPage();else if(['deposit','withdraw','transfer'].includes(route))moneyPage(route);else if(route==='transactions')transactionsPage();else if(route==='profile')profilePage();else location.hash='dashboard';
  }
 }catch(err){if(version===state.routeVersion&&err.status!==401){shell(route,`<section class="card"><div class="form-error">${esc(err.message)}</div><button class="btn" data-action="retry">Try again</button></section>`);}}finally{clearTimeout(loadingTimer);if(version===state.routeVersion){document.body.classList.remove('is-loading');app.removeAttribute('aria-busy');}}
}
document.addEventListener('click',async e=>{
 const go=e.target.closest('[data-go]');if(go&&!go.disabled)location.hash=go.dataset.go;
 const pw=e.target.closest('[data-password]');if(pw){const input=document.getElementById(pw.dataset.password);input.type=input.type==='password'?'text':'password';pw.setAttribute('aria-label',input.type==='password'?'Show password':'Hide password');pw.innerHTML=icon(input.type==='password'?'eye':'eye-off');renderIcons();}
 const action=e.target.closest('[data-action]')?.dataset.action;
 if(action==='pin-profile'){closeModal();}
 if(action==='setup-pin')setupPin();
 if(action==='logout'){try{await api('/logout',{method:'POST'});state.user=null;state.reveal=false;await csrf();location.hash='login';}catch(err){toast(err.message);}}


 if(action==='close-modal')closeModal(true);if(action==='retry')renderRoute();
 if(action==='flip-account') {
  const card=e.target.closest('.flip-shell'),flipped=!card.classList.contains('is-flipped');
  card.classList.toggle('is-flipped',flipped);
  const front=card.querySelector('.flip-front'),back=card.querySelector('.flip-back');
  front.inert=flipped;front.setAttribute('aria-hidden',String(flipped));back.inert=!flipped;back.setAttribute('aria-hidden',String(!flipped));
  const toggle=card.querySelector('.flip-toggle');toggle.setAttribute('aria-expanded',String(flipped));toggle.querySelector('span').textContent=flipped?'Hide details':'Show details';
 }
 if(action==='toggle-account-number') {
 const card=e.target.closest('.flip-shell'),revealed=card.dataset.numberRevealed!=='true';card.dataset.numberRevealed=String(revealed);
 card.querySelectorAll('[data-account-number]').forEach(el=>el.textContent=revealed?state.account.number:masked(state.account.number));
 card.querySelectorAll('.number-toggle').forEach(button=>{button.setAttribute('aria-pressed',String(revealed));button.setAttribute('aria-label',revealed?'Hide account number':'Show account number');button.innerHTML=icon(revealed?'eye-off':'eye');});renderIcons();
 }
 if(action==='reveal'){state.reveal=!state.reveal;document.getElementById('balance-number').textContent=state.reveal?state.account.number:masked(state.account.number);const b=e.target.closest('button');b.innerHTML=`${icon(state.reveal?'eye-off':'eye')}<span>${state.reveal?'Hide':'Show'} number</span>`;renderIcons();}
 const tx=e.target.closest('[data-transaction]');if(tx){try{receipt(await api(`/transactions/${tx.dataset.transaction}`));}catch(err){toast(err.message);}}
 const atx=e.target.closest('[data-admin-transaction]');if(atx){const t=state.adminTransactions.find(t=>t.id===Number(atx.dataset.adminTransaction));if(t)receipt(t);}
});
document.addEventListener('keydown',e=>{if(!overlay.firstChild)return;if(e.key==='Escape'){e.preventDefault();closeModal(true);}if(e.key==='Tab'){const elements=[...overlay.querySelectorAll('button:not(:disabled),input,textarea,a[href],select')];const first=elements[0],last=elements.at(-1);if(e.shiftKey&&document.activeElement===first){last?.focus();e.preventDefault();}else if(!e.shiftKey&&document.activeElement===last){first?.focus();e.preventDefault();}}});
window.addEventListener('hashchange',()=>{state.filter='ALL';state.search='';window.scrollTo({top:0,behavior:'instant'});renderRoute();});
(async()=>{try{await csrf();const session=await api('/session',{cache:'no-store'});state.user=session.authenticated?session.user:null;}catch{}await renderRoute();})();






